{
  "probability": 0.95,
  "range_low": 0.90,
  "range_high": 0.98,
  "summary": [
    "Early 2026 data show around 606 Mediterranean deaths by late February, indicating a sharp and concerning pace.",
    "Historically, annual Mediterranean tolls are in the 2,000–2,500 range, making 1,000 deaths by end-April plausible if the pace persists.",
    "Upward signals from pace, historical baseline, and 2025 toll dominate, though SAR/policy changes and data reporting gaps inject uncertainty.",
    "Calibrated toward a high-confidence view with a 95% posterior probability, acknowledging remaining near-term volatility."
  ],
  "confidence": "high",
  "narrative": "From a modest anchor in the reference class, strong early-2026 fatality signals and a high prior annual toll push the probability toward a 95% posterior for reaching at least 1,000 deaths by May. Still, policy shifts and data reporting lags keep some uncertainty about the exact timing and total."
  ,
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference class is IOM Missing Migrants Project annual fatalities on the Central Mediterranean route. An anchor of 0.35 reflects a cautious starting probability for reaching 1,000 deaths by end-April given typical monthly distributions, prior to incorporating 2026 signals."
    },
    "factor_updates": [
      {
        "factor": "Pace of early-2026 Mediterranean fatalities",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by Feb 23 indicate a pace that could reach 1,000 by end-April if it continues."
      },
      {
        "factor": "Historical annual toll baseline (2,000–2,500 per year)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A high annual toll makes a substantial early-year total more plausible."
      },
      {
        "factor": "Recent 2025 toll as baseline indicating ongoing risk in the Med",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "2,185 deaths in 2025 underscore persistent fatality risk across years."
      },
      {
        "factor": "Weather/sea-state conditions in March–April 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Harsh seas could raise crossing danger and fatalities."
      },
      {
        "factor": "Policy crackdown on irregular migration in Europe",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Tighter controls could reduce crossings and fatalities."
      },
      {
        "factor": "Data reporting gaps and revision risk",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Lag and revisions add uncertainty but do not strongly move the posterior in either direction."
      },
      {
        "factor": "Sustained SAR capacity and policy responses",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Improved rescue operations could reduce fatalities, tempering upside."
      }
    ],
    "synthesis_rationale": "Starting from a cautious anchor (0.35) and incorporating multiple strong up signals (pace, baseline, 2025 toll) with countervailing down pressures (policy, SAR capacity) yields a high posterior around 0.95. The calibration acknowledges data lags and potential near-term volatility; the final range reflects remaining uncertainty despite a strong directional tilt upward."
  }
}

